-- ================================================================================================
-- NaturDex · datos semilla (DML)
-- ------------------------------------------------------------------------------------------------
-- Carga el parque piloto "Cabo Cope y Puntas de Calnegre" y su catálogo (15 hábitats oficiales,
-- 76 especies, 16 puntos de interés) y sus relaciones. Idempotente (INSERT ... ON DUPLICATE KEY /
-- INSERT IGNORE / DELETE / UPDATE), se puede reejecutar sin duplicar.
-- Requiere el esquema ya creado: ejecuta antes Database/schema.sql.
--     mysql < Database/schema.sql
--     mysql < Database/seed.sql
-- ================================================================================================
-- El fichero es UTF-8, pero el cliente mysql puede conectar en latin1 (p. ej. al importarlo el
-- entrypoint del contenedor de MySQL): sin esta línea las tildes/ñ se guardarían dobles (mojibake).
SET NAMES utf8mb4;
USE naturadex;

INSERT INTO parks (slug, name, category, region, province, municipality, description, coastline_km, latitude, longitude, status)
VALUES ('cabo-cope-puntas-calnegre','Cabo Cope y Puntas de Calnegre','Parque Regional','Región de Murcia','Murcia','Águilas y Lorca','Espacio litoral protegido con calas, acantilados, matorral semiárido y praderas marinas. Este parque es el piloto de NaturDex.',17.00,37.501600,-1.449250,'available')
ON DUPLICATE KEY UPDATE name = VALUES(name), category = VALUES(category), region = VALUES(region), province = VALUES(province), municipality = VALUES(municipality), description = VALUES(description), coastline_km = VALUES(coastline_km), status = VALUES(status), updated_at = CURRENT_TIMESTAMP;

-- Paisaje Protegido de Cuatro Calas (Águilas). Declarado por la Ley 4/1992 y LIC/ZEC de la Red
-- Natura 2000 (ES6200010, ~172 ha). ~222 ha de litoral, ramblas y lomas semidesérticas entre Calarreona y Los
-- Cocedores, en el límite con Almería. Se crea como FICHA BASE (status 'basic'): tiene su límite
-- oficial y sus códigos Natura 2000, pero el catálogo de hábitats/especies/POIs está en preparación.
-- Las coordenadas son un centro aproximado del espacio (para encuadrar el mini-mapa del panel);
-- ajústalo desde el selector de coordenadas.
INSERT INTO parks (slug, name, category, region, province, municipality, description, area_hectares, coastline_km, latitude, longitude, status)
VALUES ('cuatro-calas','Cuatro Calas','Paisaje Protegido','Región de Murcia','Murcia','Águilas','Paisaje Protegido del litoral suroccidental de Águilas: cuatro calas vírgenes (Calarreona, La Higuerica, La Carolina y Los Cocedores) con ramblas y lomas semidesérticas, en el límite con la provincia de Almería.',222.00,NULL,37.382500,-1.632000,'basic')
ON DUPLICATE KEY UPDATE name = VALUES(name), category = VALUES(category), region = VALUES(region), province = VALUES(province), municipality = VALUES(municipality), description = VALUES(description), area_hectares = VALUES(area_hectares), latitude = VALUES(latitude), longitude = VALUES(longitude), status = VALUES(status), updated_at = CURRENT_TIMESTAMP;

-- Hábitats de interés comunitario (Directiva 92/43/CEE) presentes en el Parque Regional Calnegre
-- y Cabo Cope: lista oficial de 15 hábitats (11 terrestres + 4 litorales) que el documento previo
-- del PORN (CARM, 2021) atribuye a los LIC de Calnegre y Cabo Cope. Se depuró un catálogo previo más
-- amplio dejando solo estos 15; quedan fuera 6 códigos que no figuran en esa lista oficial: 3 marinos
-- (1120 Posidonia, 1110 bancos de arena, 1170 arrecifes, probablemente de la ZEC marina adyacente
-- ES6200029) y 3 solo documentados en el Anexo I del proyecto de PORN/ANSE (2240, 3280, 7210).
-- Las coordenadas son un punto representativo del hábitat dentro del parque (para el círculo del
-- mapa), no su extensión real; se sustituirán por polígonos cuando llegue la cartografía QGIS.
INSERT INTO habitats (park_id, slug, code, name, habitat_type, description, is_priority, latitude, longitude, color, review_note)
SELECT p.id, h.slug, h.code, h.name, h.habitat_type, h.description, h.is_priority, h.latitude, h.longitude, h.color, h.review_note
FROM parks p
JOIN (
    SELECT 'acantilados' slug, '1240' code, 'Acantilados mediterráneos con Limonium' name, 'Litoral' habitat_type, 'litoral del parque piloto' description, FALSE is_priority, NULL latitude, NULL longitude, '#8b5e34' color, NULL review_note
    UNION ALL
    SELECT 'matorral-semiarido' slug, '5330' code, 'Matorral termomediterráneo semiárido' name, 'Terrestre' habitat_type, 'terrestre del parque piloto' description, FALSE is_priority, NULL latitude, NULL longitude, '#2f6f4e' color, NULL review_note
    UNION ALL
    SELECT 'azufaifar' slug, '5220' code, 'Matorrales arborescentes de Ziziphus' name, 'Terrestre' habitat_type, 'terrestre del parque piloto' description, TRUE is_priority, NULL latitude, NULL longitude, '#6f8f3a' color, NULL review_note
    UNION ALL
    SELECT 'matorral-halofilo' slug, '1420' code, 'Matorrales halófilos mediterráneos y termoatlánticos' name, 'Terrestre' habitat_type, 'terrestre del parque piloto, marina de Cope' description, FALSE is_priority, NULL latitude, NULL longitude, '#7a6a3a' color, NULL review_note
    UNION ALL
    SELECT 'matorral-halonitrofilo' slug, '1430' code, 'Matorrales halo-nitrófilos' name, 'Terrestre' habitat_type, 'terrestre del parque piloto, marina de Cope' description, FALSE is_priority, NULL latitude, NULL longitude, '#9a7b3f' color, NULL review_note
    UNION ALL
    SELECT 'galeria-ribera' slug, '92D0' code, 'Galerías y matorrales ribereños termomediterráneos' name, 'Terrestre' habitat_type, 'terrestre del parque piloto, ramblas' description, FALSE is_priority, NULL latitude, NULL longitude, '#3f7a5a' color, NULL review_note
    UNION ALL
    SELECT 'veg-anual-desechos-marinos' slug, '1210' code, 'Vegetación anual sobre desechos marinos acumulados' name, 'Litoral' habitat_type, 'comunidades pioneras sobre la línea de acumulación de restos marinos en las playas del parque' description, FALSE is_priority, NULL latitude, NULL longitude, '#c9a66b' color, NULL review_note
    UNION ALL
    SELECT 'estepas-salinas-albardinal' slug, '1510' code, 'Estepas salinas mediterráneas (Limonietalia)' name, 'Terrestre' habitat_type, 'albardinal (Lygeum spartum) sobre suelos salinos de la marina de Cope, asociado a Limonium insigne' description, TRUE is_priority, NULL latitude, NULL longitude, '#b3577a' color, NULL review_note
    UNION ALL
    SELECT 'dunas-embrionarias' slug, '2110' code, 'Dunas móviles embrionarias' name, 'Litoral' habitat_type, 'primer cordón dunar en formación activa junto a la orilla' description, FALSE is_priority, NULL latitude, NULL longitude, '#e0c56a' color, NULL review_note
    UNION ALL
    SELECT 'dunas-malcomietalia' slug, '2230' code, 'Dunas con céspedes del Malcomietalia' name, 'Litoral' habitat_type, 'céspedes anuales sobre arenas dunares estabilizadas' description, FALSE is_priority, NULL latitude, NULL longitude, '#d9b97e' color, 'Cartografiado con una fuente distinta a la del resto de hábitats: la cartografía de hábitats terrestres de la Región de Murcia (CARM, 2020), porque este código no aparece en los recintos del Inventario Español de Hábitats (INB) dentro del parque. Su presencia y delimitación exactas dentro del parque quedan pendientes de revisión.' review_note
    UNION ALL
    SELECT 'rios-glaucium' slug, '3250' code, 'Ríos mediterráneos de caudal permanente con Glaucium flavum' name, 'Terrestre' habitat_type, 'cauces y ramblas con lámina de agua permanente colonizados por la amapola marina' description, FALSE is_priority, NULL latitude, NULL longitude, '#6f9270' color, 'Cartografiado con una fuente distinta a la del resto de hábitats: la cartografía de hábitats terrestres de la Región de Murcia (CARM, 2020), porque este código no aparece en los recintos del Inventario Español de Hábitats (INB) dentro del parque. Su presencia y delimitación exactas dentro del parque quedan pendientes de revisión.' review_note
    UNION ALL
    SELECT 'sabinar-juniperus' slug, '5210' code, 'Matorrales arborescentes de Juniperus spp.' name, 'Terrestre' habitat_type, 'sabinar (Juniperus phoenicea) sobre laderas y cerros del interior del parque' description, FALSE is_priority, NULL latitude, NULL longitude, '#3f6b4a' color, 'Cartografiado con una fuente distinta a la del resto de hábitats: la cartografía de hábitats terrestres de la Región de Murcia (CARM, 2020), porque este código no aparece en los recintos del Inventario Español de Hábitats (INB) dentro del parque. Su presencia y delimitación exactas dentro del parque quedan pendientes de revisión.' review_note
    UNION ALL
    SELECT 'prados-alysso-sedion' slug, '6110' code, 'Prados calcáreos cársticos o basófilos del Alysso-Sedion albi' name, 'Terrestre' habitat_type, 'pastizales de terófitos y crasuláceas sobre suelos esqueléticos calcáreos de los cerros carbonatados' description, TRUE is_priority, NULL latitude, NULL longitude, '#9c8a5e' color, 'Cartografiado con una fuente distinta a la del resto de hábitats: la cartografía de hábitats terrestres de la Región de Murcia (CARM, 2020), porque este código no aparece en los recintos del Inventario Español de Hábitats (INB) dentro del parque. Su presencia y delimitación exactas dentro del parque quedan pendientes de revisión.' review_note
    UNION ALL
    SELECT 'subestepa-thero-brachypodietea' slug, '6220' code, 'Zonas subestépicas de gramíneas y anuales del Thero-Brachypodietea' name, 'Terrestre' habitat_type, 'pastizales terofíticos mediterráneos sobre suelos oligotróficos de llanos y laderas abiertas' description, TRUE is_priority, NULL latitude, NULL longitude, '#b0a066' color, NULL review_note
    UNION ALL
    SELECT 'roquedos-casmofiticos' slug, '8210' code, 'Pendientes rocosas calcícolas con vegetación casmofítica' name, 'Terrestre' habitat_type, 'roquedos y cortados calcáreos con vegetación fisurícola, con Teucrium freynii como especie característica' description, FALSE is_priority, NULL latitude, NULL longitude, '#8a7a6a' color, NULL review_note
) h
WHERE p.slug = 'cabo-cope-puntas-calnegre'
ON DUPLICATE KEY UPDATE name = VALUES(name), habitat_type = VALUES(habitat_type), description = VALUES(description),
    is_priority = VALUES(is_priority), latitude = VALUES(latitude), longitude = VALUES(longitude), color = VALUES(color),
    slug = VALUES(slug), review_note = VALUES(review_note);

-- Fotos de hábitat (URL externa, Wikimedia Commons). Solo se rellenan las candidatas con confianza
-- media-alta/alta y especie/comunidad diagnóstica coincidente (NaturDex_fotos_candidatas.xlsx). Las
-- de confianza media/baja se dejan sin foto (portada temática generada) hasta verificarlas a mano.
-- Licencia de cada archivo pendiente de verificar en su ficha de Commons antes de publicar.
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Lygeum_spartum_Closeup_12July2009_LagunadelaMata.jpg' WHERE h.slug = 'estepas-salinas-albardinal';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/-0591_Anabasis_articulata,_d%C3%A9sert_d%27Almeria,_Espagne_P1110397.JPG' WHERE h.slug = 'matorral-semiarido';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus_phoenicea_4.JPG' WHERE h.slug = 'sabinar-juniperus';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Zizyphus_lotus.JPG' WHERE h.slug = 'azufaifar';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Escobilla_-_Salsola_genistoides.jpg' WHERE h.slug = 'matorral-halonitrofilo';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Sarcocornia_perennis_kz01.jpg' WHERE h.slug = 'matorral-halofilo';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Close-up_of_a_vegetation_of_the_Alysso-Sedion.jpg' WHERE h.slug = 'prados-alysso-sedion';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cakile_maritima_b.jpg' WHERE h.slug = 'veg-anual-desechos-marinos';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
    SET h.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_hivern_Canyelles.jpg' WHERE h.slug = 'subestepa-thero-brachypodietea';

-- Poda de hábitats fuera de la lista oficial de 15 del PORN (CARM, 2021) para los LIC de Calnegre
-- y Cabo Cope. El catálogo anterior llegó a tener 21; se retiran 6 códigos que no figuran en esa
-- lista (3 marinos —1120/1110/1170, probablemente de la ZEC marina adyacente ES6200029— y 3 solo
-- del Anexo I del proyecto de PORN/ANSE —2240/3280/7210—). Necesario porque el INSERT idempotente
-- de arriba no elimina filas ya existentes en la base de datos. Los enlaces en species_habitats
-- se borran solos por la FK ON DELETE CASCADE.
DELETE h FROM habitats h
JOIN parks p ON p.id = h.park_id
WHERE p.slug = 'cabo-cope-puntas-calnegre'
  AND h.slug IN ('posidonia', 'banco-arena', 'arrecifes', 'dunas-brachypodietalia', 'rios-paspalo-agrostidion', 'turberas-cladium');

-- Puntos de observación/interés del parque piloto.
-- Coordenadas verificadas/corregidas con topónimos de OpenStreetMap (© OpenStreetMap contributors, ODbL);
-- fotos de Wikimedia Commons con atribución en el campo source; los sitios geológicos/arqueológicos/
-- paleontológicos citan el Anexo I del proyecto de PORN (ANSE) u otras fuentes primarias. is_approx=1
-- marca posiciones representativas/estimadas, no coordenadas de campo verificadas. Ver README para el
-- aviso sobre 4 puntos históricos (Puntas de Calnegre, Playa de Calnegre, Lomo de Bas, Calabardina) que,
-- pese a estar geolocalizados correctamente, caen entre 200 y 660 m fuera del polígono oficial del
-- Parque Regional (núcleos urbanos y cumbres justo en su límite).
INSERT INTO points_of_interest (park_id, slug, name, type, description, latitude, longitude, image_url, source, is_approx)
SELECT p.id, poi.slug, poi.name, poi.type, poi.description, poi.latitude, poi.longitude, poi.image_url, poi.source, poi.is_approx
FROM parks p
JOIN (
    SELECT 'torre-cope' slug, 'Torre de Cope' name, 'Cultural' type, 'Torre vigía costera del siglo XVI, construida para la defensa frente a la piratería berberisca que asolaba el litoral murciano. Catalogada como Bien de Interés Cultural. Junto a ella se levantó la Ermita de Cope, que daba servicio religioso a su guarnición.' description, 37.43695 latitude, -1.48441 longitude, 'Img/poi/torre-cope.jpg' image_url, 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Jose Lorca, dominio público); Región de Murcia Digital (CARM)' source, FALSE is_approx
    UNION ALL
    SELECT 'cabo-cope' slug, 'Cabo Cope' name, 'Paisajístico' type, 'Promontorio litoral y mirador natural sobre la bahía de Mazarrón. El macizo calizo de Cabo Cope está catalogado como Lugar de Interés Geológico: en él aflora muy bien representado el Complejo Maláguide (calizas, micaesquistos y cuarcitas), con interés geomorfológico, estratigráfico y neotectónico, además de su interés cultural.' description, 37.427932 latitude, -1.493014 longitude, 'Img/poi/cabo-cope.jpg' image_url, 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: J.Alberto, CC BY-SA 4.0)' source, FALSE is_approx
    UNION ALL
    SELECT 'puntas-calnegre' slug, 'Puntas de Calnegre' name, 'Paisajístico' type, 'Núcleo litoral en el extremo norte del parque, con playas, gravas, calas y vistas abiertas al Mediterráneo, en el tramo donde Lomo de Bas termina en el mar.' description, 37.507796 latitude, -1.403058 longitude, 'Img/poi/puntas-calnegre.jpg' image_url, 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Pau lopezca, CC BY-SA 3.0 ES); Región de Murcia Digital (CARM)' source, FALSE is_approx
    UNION ALL
    SELECT 'playa-calnegre' slug, 'Playa de Calnegre' name, 'Paisajístico' type, 'Cala de arena y grava dentro del entorno protegido, punto de acceso habitual a la ruta litoral del GR-92 hacia Puntas de Calnegre.' description, 37.506887 latitude, -1.416314 longitude, 'Img/poi/playa-calnegre.jpg' image_url, 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Mueca, CC BY-SA 4.0)' source, FALSE is_approx
    UNION ALL
    SELECT 'cala-blanca' slug, 'Cala Blanca' name, 'Geológico' type, 'Tramo costero de interés geomorfológico. Aquí afloran cuarcitas, micaesquistos, filitas y conglomerados triásicos del Complejo Alpujárride, visibles en los barrancos y el contacto con el mar.' description, 37.48348 latitude, -1.46224 longitude, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cala_blanca_2.JPG' image_url, 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM)' source, FALSE is_approx
    UNION ALL
    SELECT 'lomo-bas' slug, 'Lomo de Bas' name, 'Geológico' type, 'Relieve interior que ayuda a leer el contraste entre las sierras litorales, las ramblas y la costa semiárida. Sus laderas suaves enlazan geomorfológicamente con la unidad de la Marina de Cope.' description, 37.511086 latitude, -1.457429 longitude, 'Img/poi/lomo-bas.jpg' image_url, 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 ES)' source, FALSE is_approx
    UNION ALL
    SELECT 'calabardina' slug, 'Calabardina' name, 'Acceso' type, 'Núcleo costero de Águilas que funciona como puerta de entrada meridional al parque, al pie del macizo de Cabo Cope. En época púnica y romana funcionó como fondeadero protegido de los vientos de levante; la zona ha dado hallazgos continuos de ánforas de origen púnico y de todos los periodos romanos por su buen abrigo natural.' description, 37.43452 latitude, -1.50347 longitude, 'Img/poi/calabardina.jpg' image_url, 'Región de Murcia Digital (CARM) - Águilas, Yacimientos; Wikimedia Commons (foto: Rietje Swart, CC BY-SA 2.0)' source, FALSE is_approx
    UNION ALL
    SELECT 'playa-Charco' slug, 'Playa del Charco' name, 'Natural' type, 'Playa con uno de los mejores tarayales (Tamarix) del litoral murciano; el PORN la cita por su bosque de tarais, representativo del hábitat de interés comunitario 92D0 (galerías y matorrales ribereños termomediterráneos).' description, 37.449442 latitude, -1.482124 longitude, NULL image_url, 'Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021); OpenStreetMap contributors (ODbL)' source, FALSE is_approx
    UNION ALL
    SELECT 'ermita-cope' slug, 'Ermita de Cope' name, 'Religioso' type, 'Ermita del siglo XVIII que daba servicio religioso a la guarnición de la Torre de Cope, junto a la que se levanta. Según la tradición local recogida en fuentes de turismo regional, fue destruida por un incendio provocado en un ataque pirata, salvándose solo la talla de la cabeza del Cristo, hoy muy venerada; este episodio concreto está pendiente de contrastar con una fuente documental primaria.' description, 37.43563 latitude, -1.48484 longitude, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panor%C3%A1mica_de_la_Torre_de_Cope_y_el_Golfo_de_Mazarr%C3%B3n.jpg' image_url, 'OpenStreetMap contributors (ODbL); tradición oral recogida en fuentes de turismo regional (episodio del incendio pendiente de contrastar con fuente documental primaria)' source, FALSE is_approx
    UNION ALL
    SELECT 'dunas-fosiles-cope' slug, 'Dunas fósiles de Cabo Cope' name, 'Geológico' type, 'Playas y dunas fósiles del Eutirreniense (Pleistoceno), formadas por calcarenitas de origen marino litoral muy erosionables por la acción del agua, que han originado numerosas oquedades y cavidades costeras. El Anexo I del proyecto de PORN las señala como uno de los valores geomorfológicos y paleogeográficos más singulares de la línea de costa del parque.' description, 37.441423 latitude, -1.484144 longitude, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torre_de_Cope.JPG' image_url, 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM)' source, TRUE is_approx
    UNION ALL
    SELECT 'yacimientos-garrobillo' slug, 'Yacimientos paleontológicos de Garrobillo' name, 'Paleontológico' type, 'Garrobillo 1 y Garrobillo 2, parte de la Cuenca de Cope (Arco de Águilas, Zonas Internas Béticas). Garrobillo 1 muestra el contacto de los materiales neógenos con el basamento metamórfico bético; Garrobillo 2 conserva calcarenitas bioclásticas con concentraciones del foraminífero Lenticulina spp. y de pectínidos de origen tormentoso.' description, 37.494 latitude, -1.498 longitude, NULL image_url, 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM). Posición representativa del paraje El Garrobillo; las coordenadas exactas de cada yacimiento no están publicadas.' source, TRUE is_approx
    UNION ALL
    SELECT 'yacimientos-cope-galera' slug, 'Yacimientos paleontológicos de Galera-Cope' name, 'Paleontológico' type, 'Galera-1, Cope 1 y Cope 2, en el extremo sur de la Cuenca de Cope. Galera-1 documenta la transgresión pliocena mediante facies excepcionales de washover fans; Cope 1 y Cope 2, junto al saladar, aportan marcadores bioestratigráficos que sitúan temporalmente los eventos de la cuenca durante el Plioceno.' description, 37.471473 latitude, -1.469368 longitude, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_Cope_-_WLE_Spain_2015.jpg' image_url, 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM). Posición representativa junto al saladar y la Playa de la Galera; las coordenadas exactas de cada yacimiento no están publicadas.' source, TRUE is_approx
    UNION ALL
    SELECT 'fuente-piratas' slug, 'Fuente de los piratas' name, 'Natural' type, 'Ensenada de la Fuente, cala al este de Cabo Cope que toma su nombre de un manantial de agua dulce junto al que se levanta la Torre de Cope. Fue punto de aguada para la guarnición de la torre y, según la tradición oral recogida en fuentes de turismo regional, también lo usaban las embarcaciones berberiscas que hostigaban la costa (de ahí el nombre popular).' description, 37.433713 latitude, -1.483251 longitude, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ensenada_de_la_Fuente.jpg' image_url, 'Wikipedia - "Cabo Cope"; descubriendomurcia.com; tradición oral recogida en fuentes de turismo regional (nombre popular pendiente de confirmar con fuente documental primaria)' source, TRUE is_approx
    UNION ALL
    SELECT 'punta-cabricas' slug, 'Punta de las Cabricas' name, 'Paisajístico' type, 'Saliente rocoso del litoral entre Cabo Cope y Calabardina, con acantilados característicos de este tramo costero del parque y buenas vistas hacia el macizo de Cope.' description, 37.43294 latitude, -1.47693 longitude, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puntas_de_Calnegre%2C_desde_Piedras_Negras.JPG' image_url, 'OpenStreetMap contributors (ODbL)' source, FALSE is_approx
    UNION ALL
    SELECT 'ruinas-garrobillo' slug, 'Ruinas de la aldea de El Garrobillo' name, 'Cultural' type, 'Restos de El Garrobillo, antigua pedanía agrícola del término de Lorca en la Marina de Cope, hoy despoblada. Junto a Ramonete, forma parte de los núcleos rurales tradicionales vinculados al aprovechamiento agrícola histórico de esta zona del parque.' description, 37.49241 latitude, -1.49957 longitude, NULL image_url, 'OpenStreetMap contributors (ODbL) - topónimo "El Garrobillo"; referencias generales a las pedanías históricas de Ramonete y El Garrobillo en el término de Lorca. Ubicación aproximada (posición del paraje, no de una edificación concreta verificada en campo).' source, TRUE is_approx
) poi
WHERE p.slug = 'cabo-cope-puntas-calnegre'
ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), type = VALUES(type),
    latitude = VALUES(latitude), longitude = VALUES(longitude), image_url = VALUES(image_url),
    source = VALUES(source), is_approx = VALUES(is_approx);

