-- Catálogo de especies semilla, con taxonomía completa y tres niveles de estatus de conservación
-- (IUCN Global, Lista Roja/Catálogo nacional español, Catálogo Regional de Murcia), citando fuente por registro.
-- Fuentes generales: Región de Murcia Digital / CARM; Wikipedia "Parque regional de Cabo Cope y Puntas de Calnegre";
-- Alcaraz Ariza, F.J. "La Marina de Cope: ¿los últimos días de un paraíso botánico?" (Eubacteria nº5, Universidad de Murcia);
-- Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia;
-- Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia;
-- Lista Roja 2008 de la Flora Vascular Española (MITECO / listaroja.conservacionvegetal.org);
-- IUCN Red List of Threatened Species (evaluación global).
-- IMPORTANTE: varios registros incluyen review_note señalando incertidumbres (identificación, sinonimia o presencia
-- exacta en Cabo Cope) para que un especialista los revise antes de un uso definitivo. Ver README para el listado.
INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status,
    description, identification_tips, seasonality, image_url, latitude, longitude, rarity_score, is_featured, source,
    taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note)
SELECT p.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status,
    s.description, s.identification_tips, s.seasonality, s.image_url, s.latitude, s.longitude, s.rarity_score, s.is_featured, s.source,
    s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note
FROM parks p
JOIN (
    SELECT 'Tortuga mora' common_name, 'Testudo graeca' scientific_name, 'fauna' kingdom, 'Reptil' family, 'Matorral termomediterráneo semiárido' primary_habitat, 'Amenazada' conservation_status, 'Reptil terrestre emblemático de ambientes áridos, matorrales mediterráneos y zonas abiertas del sureste ibérico.' description, 'Caparazón abombado; Actividad en horas templadas; No manipular ni desplazar ejemplares' identification_tips, 'Primavera y otoño' seasonality, 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Testudo_graeca_Lambert_01.jpg/640px-Testudo_graeca_Lambert_01.jpg' image_url, NULL latitude, NULL longitude, 5 rarity_score, TRUE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25' source, 'Chordata' taxon_phylum, 'Reptilia' taxon_class, 'Testudines' taxon_order, 'Testudinidae' taxon_family, 'Testudo' taxon_genus, 'VU A1cd (evaluación IUCN de 1996; pendiente de reevaluación global reciente)' iucn_global, 'Catálogo Español de Especies Amenazadas / LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Hábitats 92/43/CEE, Anexos II y IV; Reglamento CITES (CE) 338/97, Anexo A' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: En peligro de extinción' murcia_status, NULL review_note
    UNION ALL
    SELECT 'Águila perdicera' common_name, 'Aquila fasciata' scientific_name, 'fauna' kingdom, 'Ave rapaz' family, 'Cortados y áreas abiertas' primary_habitat, 'Amenazada' conservation_status, 'Rapaz mediterránea asociada a sierras, cortados y territorios de campeo amplios.' description, 'Silueta grande y vuelo potente; Observar a distancia; Evitar molestias en zonas de nidificación' identification_tips, 'Todo el año' seasonality, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Bonellis_Eagle_Aquila_fasciata_by_Dr._Raju_Kasambe_DSCN1709_%2810%29.jpg/640px-Bonellis_Eagle_Aquila_fasciata_by_Dr._Raju_Kasambe_DSCN1709_%2810%29.jpg' image_url, NULL latitude, NULL longitude, 5 rarity_score, TRUE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre; Libro Rojo de las Aves de España, SEO/BirdLife 2004; Ley 7/1995, de 21 de abril, de la Fauna Silvestre de la Región de Murcia (Anexo I); IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Accipitriformes' taxon_order, 'Accipitridae' taxon_family, 'Aquila' taxon_genus, 'LC (población global amplia en Asia y África pese al declive europeo)' iucn_global, 'Catálogo Español de Especies Amenazadas: Vulnerable; Libro Rojo de las Aves de España (SEO/BirdLife, 2004/2021); Directiva Aves 2009/147/CE, Anexo I' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: En peligro de extinción (población reproductora muy reducida)' murcia_status, NULL review_note
    UNION ALL
    SELECT 'Camachuelo trompetero' common_name, 'Bucanetes githagineus' scientific_name, 'fauna' kingdom, 'Ave esteparia' family, 'Paisaje árido y matorral bajo' primary_habitat, 'Interés especial' conservation_status, 'Ave ligada a paisajes semiáridos, con gran valor como indicador de biodiversidad esteparia.' description, 'Pico robusto; Tonos rosados discretos; Suele moverse en pequeños grupos' identification_tips, 'Primavera y verano' seasonality, 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Bucanetes_githagineus_2.jpg/640px-Bucanetes_githagineus_2.jpg' image_url, NULL latitude, NULL longitude, 4 rarity_score, TRUE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Passeriformes' taxon_order, 'Fringillidae' taxon_family, 'Bucanetes' taxon_genus, 'LC' iucn_global, 'Catalogado como Vulnerable en el Libro Rojo de las Aves de España (población ibérica escasa y localizada)' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial' murcia_status, NULL review_note
    UNION ALL
    SELECT 'Cormorán moñudo' common_name, 'Gulosus aristotelis' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Litoral rocoso' primary_habitat, 'Protección especial' conservation_status, 'Ave marina de costas rocosas, islotes y aguas someras donde busca alimento.' description, 'Plumaje oscuro; Nada bajo sobre el agua; Penacho visible en época nupcial' identification_tips, 'Todo el año' seasonality, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/European_shag_%28Phalacrocorax_aristotelis%29.jpg/640px-European_shag_%28Phalacrocorax_aristotelis%29.jpg' image_url, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Suliformes' taxon_order, 'Phalacrocoracidae' taxon_family, 'Gulosus' taxon_genus, 'LC' iucn_global, 'Subespecie mediterránea (desmarestii) catalogada Vulnerable en el Catálogo Español de Especies Amenazadas' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial' murcia_status, 'Reclasificado taxonómicamente de Phalacrocorax aristotelis a Gulosus aristotelis; confirmar si la población litoral pertenece a la subespecie desmarestii.' review_note
    UNION ALL
    SELECT 'Lagarto ocelado' common_name, 'Timon lepidus' scientific_name, 'fauna' kingdom, 'Reptil' family, 'Matorral termomediterráneo semiárido' primary_habitat, 'Protección especial' conservation_status, 'Uno de los mayores lagartos de Europa, ligado a roquedos soleados y matorral mediterráneo bien conservado.' description, 'Coloración verde con ocelos azules; Adultos de gran tamaño (hasta 60 cm); Muy territorial y termorregulador' identification_tips, 'Primavera a otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Timon_lepidus_b.JPG' image_url, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre' source, 'Chordata' taxon_phylum, 'Reptilia' taxon_class, 'Squamata' taxon_order, 'Lacertidae' taxon_family, 'Timon' taxon_genus, 'NT (Casi Amenazado, evaluación de 2009 por declive poblacional en parte de su área)' iucn_global, 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial' murcia_status, NULL review_note
    UNION ALL
    SELECT 'Eslizón ibérico' common_name, 'Chalcides bedriagai' scientific_name, 'fauna' kingdom, 'Reptil' family, 'Matorral termomediterráneo semiárido' primary_habitat, 'Protección especial' conservation_status, 'Reptil endémico ibérico de hábitos fosoriales, ligado a suelos sueltos y pedregosos con vegetación rala.' description, 'Cuerpo alargado y patas muy cortas; Se desplaza reptando entre hojarasca y piedras; Difícil de observar, muy escurridizo' identification_tips, 'Primavera y verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chalcides_bedriagai_02_by-dpc.jpg' image_url, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25' source, 'Chordata' taxon_phylum, 'Reptilia' taxon_class, 'Squamata' taxon_order, 'Scincidae' taxon_family, 'Chalcides' taxon_genus, 'LC' iucn_global, 'LESRPE; Directiva Hábitats 92/43/CEE, Anexo IV' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial' murcia_status, NULL review_note
    UNION ALL
    SELECT 'Búho real' common_name, 'Bubo bubo' scientific_name, 'fauna' kingdom, 'Ave rapaz nocturna' family, 'Cortados y áreas abiertas' primary_habitat, 'Protección especial' conservation_status, 'Rapaz nocturna de gran tamaño que nidifica en cortados y roquedos del parque.' description, 'Gran tamaño y penachos auriculares; Actividad crepuscular y nocturna; Ulular grave audible al atardecer' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bubo_bubo_sibiricus_-_01.JPG' image_url, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Strigiformes' taxon_order, 'Strigidae' taxon_family, 'Bubo' taxon_genus, 'LC' iucn_global, 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial' murcia_status, NULL review_note
    UNION ALL
    SELECT 'Halcón peregrino' common_name, 'Falco peregrinus' scientific_name, 'fauna' kingdom, 'Ave rapaz' family, 'Cortados y áreas abiertas' primary_habitat, 'Protección especial' conservation_status, 'Rapaz de vuelo veloz asociada a cortados costeros, donde caza aves en pleno vuelo.' description, 'Vuelo rápido en picado; Silueta compacta de alas puntiagudas; Nidifica en repisas de acantilado' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Falc%C3%A3o-peregrino_(Falco_peregrinus)_-_Peregrine_falcon.jpg' image_url, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Falconiformes' taxon_order, 'Falconidae' taxon_family, 'Falco' taxon_genus, 'LC' iucn_global, 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A' spain_status, 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial' murcia_status, NULL review_note
