    UNION ALL
    -- ===== 2230 · Dunas con céspedes del Malcolmietalia ==========================================
    SELECT 'Maresia' common_name, 'Maresia nana' scientific_name, 'flora' kingdom, 'Terófito dunar' family, 'Dunas con céspedes del Malcolmietalia' primary_habitat, 'Preocupación menor' conservation_status, 'Diminuto terófito de floración efímera primaveral, diagnóstico de los céspedes anuales sobre arenas dunares del Malcolmietalia; forma la asociación Loeflingio hispanicae-Maresietum nanae.' description, 'Planta anual diminuta; Flores lilas o blanquecinas; Solo visible en primavera lluviosa' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maresia_nana_1.jpg' image_url, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie diagnóstica del hábitat de interés comunitario 2230 (Dunas con céspedes del Malcolmietalia) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural, CARM); asociación Loeflingio hispanicae-Maresietum nanae documentada en el litoral murciano (Rivas Goday, orden Malcolmietalia; Alcaraz Ariza, Vegetación y hábitats, Universidad de Murcia).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Brassicales' taxon_order, 'Brassicaceae' taxon_family, 'Maresia' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); diagnóstica de este hábitat en el litoral murciano' murcia_status, 'Añadida como especie diagnóstica del hábitat 2230, documentada en el litoral de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.' review_note
    UNION ALL
    SELECT 'Colleja de arenal' common_name, 'Silene ramosissima' scientific_name, 'flora' kingdom, 'Terófito dunar' family, 'Dunas con céspedes del Malcolmietalia' primary_habitat, 'Preocupación menor' conservation_status, 'Colleja anual muy ramificada desde la base, característica de las dunas semifijas; da nombre a la asociación Triplachno nitentis-Silenetum ramosissimae.' description, 'Muy ramificada desde la base; Cáliz inflado con nervios marcados; Anual de vida corta' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Silene_ramosissima_1.jpg' image_url, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie diagnóstica del hábitat de interés comunitario 2230 (Dunas con céspedes del Malcolmietalia) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural, CARM); asociación Triplachno nitentis-Silenetum ramosissimae documentada en el litoral murciano.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Caryophyllaceae' taxon_family, 'Silene' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); diagnóstica de este hábitat en el litoral murciano' murcia_status, 'Añadida como especie diagnóstica del hábitat 2230, documentada en el litoral de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.' review_note
    UNION ALL
    SELECT 'Loeflingia' common_name, 'Loeflingia hispanica' scientific_name, 'flora' kingdom, 'Terófito psammófilo' family, 'Dunas con céspedes del Malcolmietalia' primary_habitat, 'Preocupación menor' conservation_status, 'Terófito minúsculo pegado al suelo, propio de arenas sueltas; componente de los céspedes anuales dunares del Malcolmietalia.' description, 'Planta minúscula pegada al suelo; Hojas lineares diminutas; Difícil de ver sin buscarla' identification_tips, 'Primavera' seasonality, NULL image_url, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie del cortejo diagnóstico del hábitat de interés comunitario 2230 (Dunas con céspedes del Malcolmietalia) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural, CARM); asociación Loeflingio hispanicae-Maresietum nanae documentada en el litoral murciano.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Caryophyllaceae' taxon_family, 'Loeflingia' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); característica de este hábitat en el litoral murciano' murcia_status, 'Añadida como especie del cortejo diagnóstico del hábitat 2230, documentada en el litoral de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.' review_note
