-- Relación especie <-> hábitat de las nuevas especies, más la asignación de la especie huérfana
-- Senecio flavus (terófito saharo-arábigo de suelos arenosos nitrificados) al matorral halo-nitrófilo.
INSERT IGNORE INTO species_habitats (species_id, habitat_id)
SELECT sp.id, h.id
FROM (
    SELECT 'Elymus farctus' scientific_name, 'dunas-embrionarias' habitat_slug
    UNION ALL SELECT 'Cyperus capitatus', 'dunas-embrionarias'
    UNION ALL SELECT 'Euphorbia paralias', 'dunas-embrionarias'
    UNION ALL SELECT 'Lotus creticus', 'dunas-embrionarias'
    UNION ALL SELECT 'Maresia nana', 'dunas-malcomietalia'
    UNION ALL SELECT 'Silene ramosissima', 'dunas-malcomietalia'
    UNION ALL SELECT 'Loeflingia hispanica', 'dunas-malcomietalia'
    UNION ALL SELECT 'Sedum sediforme', 'prados-alysso-sedion'
    UNION ALL SELECT 'Sedum album', 'prados-alysso-sedion'
    UNION ALL SELECT 'Sedum dasyphyllum', 'prados-alysso-sedion'
    UNION ALL SELECT 'Hornungia petraea', 'prados-alysso-sedion'
    UNION ALL SELECT 'Glaucium flavum', 'rios-glaucium'
    UNION ALL SELECT 'Andryala ragusina', 'rios-glaucium'
    UNION ALL SELECT 'Scrophularia canina', 'rios-glaucium'
    UNION ALL SELECT 'Dittrichia viscosa', 'rios-glaucium'
    UNION ALL SELECT 'Senecio flavus', 'matorral-halonitrofilo'
) rel
JOIN species sp ON sp.scientific_name = rel.scientific_name
JOIN habitats h ON h.slug = rel.habitat_slug
JOIN parks p ON p.id = sp.park_id AND p.id = h.park_id
WHERE p.slug = 'cabo-cope-puntas-calnegre';

-- Sedum dasyphyllum también aparece en roquedos calcáreos termófilos (8210) del parque.
INSERT IGNORE INTO species_habitats (species_id, habitat_id)
SELECT sp.id, h.id
FROM species sp
JOIN habitats h ON h.park_id = sp.park_id AND h.slug = 'roquedos-casmofiticos'
JOIN parks p ON p.id = sp.park_id
WHERE p.slug = 'cabo-cope-puntas-calnegre' AND sp.scientific_name = 'Sedum dasyphyllum';


