INSERT IGNORE INTO species_habitats (species_id, habitat_id)
SELECT sp.id, h.id
FROM (
    SELECT 'Stipa tenacissima' scientific_name, 'matorral-semiarido' habitat_slug
    UNION ALL SELECT 'Anthyllis cytisoides', 'matorral-semiarido'
    UNION ALL SELECT 'Launaea arborescens', 'matorral-semiarido'
    UNION ALL SELECT 'Launaea arborescens', 'matorral-halonitrofilo'
    UNION ALL SELECT 'Salvia rosmarinus', 'matorral-semiarido'
    UNION ALL SELECT 'Ephedra fragilis', 'matorral-semiarido'
    UNION ALL SELECT 'Ephedra fragilis', 'sabinar-juniperus'
    UNION ALL SELECT 'Ephedra fragilis', 'roquedos-casmofiticos'
    UNION ALL SELECT 'Withania frutescens', 'matorral-semiarido'
    UNION ALL SELECT 'Withania frutescens', 'azufaifar'
    UNION ALL SELECT 'Asparagus albus', 'matorral-semiarido'
    UNION ALL SELECT 'Asparagus albus', 'azufaifar'
    UNION ALL SELECT 'Asparagus albus', 'sabinar-juniperus'
    UNION ALL SELECT 'Ballota hirsuta', 'matorral-semiarido'
    UNION ALL SELECT 'Phagnalon saxatile', 'matorral-semiarido'
    UNION ALL SELECT 'Phagnalon saxatile', 'roquedos-casmofiticos'
    UNION ALL SELECT 'Teucrium capitatum', 'matorral-semiarido'
    UNION ALL SELECT 'Fagonia cretica', 'matorral-semiarido'
    UNION ALL SELECT 'Fagonia cretica', 'roquedos-casmofiticos'
    UNION ALL SELECT 'Cistus clusii', 'matorral-semiarido'
    UNION ALL SELECT 'Helianthemum almeriense', 'matorral-semiarido'
    UNION ALL SELECT 'Melica minuta', 'roquedos-casmofiticos'
) rel
JOIN species sp ON sp.scientific_name = rel.scientific_name
JOIN habitats h ON h.slug = rel.habitat_slug
JOIN parks p ON p.id = sp.park_id AND p.id = h.park_id
WHERE p.slug = 'cabo-cope-puntas-calnegre';

