-- ===== Fitosociologia + subtipos HIC por habitat (Cartografia Habitats 92/43 MITECO/BDN + planes de gestion) =====
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Limonio cymuliferi-Lycietum intricati Esteve 1973"]', h.hic_subtipos = '["1240"]'
  WHERE h.slug = 'acantilados';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Cypero mucronati-Agropyretum juncei (Kühnholtz-Lordat 1923) Br.-Bl. 1933"]', h.hic_subtipos = '["2110"]'
  WHERE h.slug = 'dunas-embrionarias';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Inulo crithmoidis-Tamaricetum boveanae Izco, Fernández-González & A. Molina 1984"]', h.hic_subtipos = '["92D0"]'
  WHERE h.slug = 'galeria-ribera';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Limonio insignis-Anabasietum hispanicae Rivas Goday & Esteve 1965","Teucrio lanigeri-Sideritetum ibanyezii Rivas Goday & Esteve 1966 corr. Alcaraz, T.E. Díaz, Rivas-Martínez & Sánchez Gómez 1989"]', h.hic_subtipos = '["5334"]'
  WHERE h.slug = 'matorral-semiarido';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Mayteno-Periplocetum angustifoliae Rivas Goday & Esteve in Rivas Goday 1959 corr. Rivas-Martínez 1975"]', h.hic_subtipos = '["5220"]'
  WHERE h.slug = 'azufaifar';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Atriplicetum glauco-halimi Rivas-Martínez & Alcaraz in Alcaraz 1984","Atriplici glaucae-Suaedetum pruinosae Rigual 1972"]', h.hic_subtipos = '["1430"]'
  WHERE h.slug = 'matorral-halonitrofilo';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Cistancho luteae-Arthrocnemetum fruticosi Géhu & Géhu-Franck 1977"]', h.hic_subtipos = '["1420"]'
  WHERE h.slug = 'matorral-halofilo';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Cosentinio bivalentis-Teucrietum freynii Rivas Goday, Esteve & Rigual 1962 corr. Alcaraz, T.E. Díaz, Rivas-Martínez & Sánchez Gómez 1989","Hypericion ericoidis Esteve 1967","Resedo paui-Sarcocapnetum saetabensis Sánchez Gómez & Alcaraz 1993"]', h.hic_subtipos = '["8211","8230"]'
  WHERE h.slug = 'roquedos-casmofiticos';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Salsolo kali-Cakiletum maritimae Costa & Mansanet 1981 corr. Rivas-Martínez, Costa & Loidi 1992"]', h.hic_subtipos = '["1210"]'
  WHERE h.slug = 'veg-anual-desechos-marinos';
UPDATE habitats h JOIN parks p ON p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET h.fitosociologia = '["Teucrio pseudochamaepytis-Brachypodietum retusi O. Bolòs 1957"]', h.hic_subtipos = '["6220"]'
