-- Backfill de evidencia para los enlaces curados previos del piloto: todos proceden de las
-- asociaciones fitosociologicas documentadas en los planes de gestion (LIC/PORN), luego son
-- 'caracteristica'. Solo rellena los que aun no tienen evidencia (no pisa 'observada_gbif'/'zepa').
UPDATE species_habitats sh
JOIN species sp ON sp.id = sh.species_id
JOIN parks p ON p.id = sp.park_id
SET sh.evidence = 'caracteristica'
WHERE p.slug = 'cabo-cope-puntas-calnegre' AND sh.evidence IS NULL;


-- ================================================================================================
-- Glosario divulgativo (NACIONAL). Terminos cientificos -> definicion en lenguaje llano. Contenido
-- editorial de NaturDex (divulgacion). Incluye la clasificacion de riesgo de la UICN (LC..EX) para
-- explicar el codigo de conservacion de cada especie. Idempotente; el frontend los resalta.
-- ================================================================================================
INSERT INTO glosario (term, definition, category, aliases, source) VALUES
  ('casmofítico', 'Que vive en las grietas y fisuras de las rocas, donde arraiga la vegetación.', 'ecología', '["casmofítica","casmofíticos","casmofíticas"]', 'NaturDex (divulgacion)'),
  ('halófilo', 'Que tolera o necesita suelos con mucha sal, como los de marismas y saladares del litoral.', 'ecología', '["halófila","halófilos","halófilas"]', 'NaturDex (divulgacion)'),
  ('halonitrófilo', 'Propio de suelos a la vez salinos y ricos en nitrógeno, frecuentes donde se acumulan restos orgánicos cerca del mar.', 'ecología', '["halonitrófila","halonitrófilos","halonitrófilas","halo-nitrófilo"]', 'NaturDex (divulgacion)'),
  ('nitrófilo', 'Que crece bien en suelos ricos en nitrógeno, como los alterados por el ganado o la actividad humana.', 'ecología', '["nitrófila","nitrófilos","nitrófilas"]', 'NaturDex (divulgacion)'),
  ('termomediterráneo', 'Del piso más cálido del clima mediterráneo, cerca de la costa y prácticamente sin heladas.', 'biogeografía', '["termomediterránea"]', 'NaturDex (divulgacion)'),
  ('fitosociología', 'Disciplina que clasifica la vegetación en comunidades de especies que suelen aparecer juntas; a cada comunidad se le asigna un nombre científico.', 'botánica', '["fitosociológica","fitosociológico","asociación fitosociológica"]', 'NaturDex (divulgacion)'),
  ('rupícola', 'Que vive sobre las rocas y los roquedos.', 'ecología', '["rupícolas"]', 'NaturDex (divulgacion)'),
  ('gipsícola', 'Que crece sobre suelos de yeso, a los que la mayoría de plantas no logra adaptarse.', 'ecología', '["gipsícolas"]', 'NaturDex (divulgacion)'),
  ('endemismo', 'Especie que solo vive de forma natural en un territorio concreto y en ningún otro lugar del mundo.', 'biogeografía', '["endémico","endémica","endémicos","endémicas"]', 'NaturDex (divulgacion)'),
  ('hábitat de interés comunitario', 'Tipo de hábitat que la Unión Europea considera valioso y protege mediante la Directiva Hábitats (92/43/CEE).', 'conservación', '["HIC","hábitats de interés comunitario"]', 'NaturDex (divulgacion)'),
  ('hábitat prioritario', 'Hábitat de interés comunitario en peligro de desaparición, al que la UE otorga máxima prioridad de conservación (Anexo I de la Directiva Hábitats).', 'conservación', '["prioritario","prioritarios"]', 'NaturDex (divulgacion)'),
  ('LESRPE', 'Listado de Especies Silvestres en Régimen de Protección Especial: catálogo español de especies protegidas por ley.', 'conservación', NULL, 'NaturDex (divulgacion)'),
  ('UICN', 'Unión Internacional para la Conservación de la Naturaleza; publica la Lista Roja, que clasifica el riesgo de extinción de cada especie en categorías (de LC, preocupación menor, a EX, extinta).', 'conservación', '["IUCN","Lista Roja"]', 'NaturDex (divulgacion)'),
  ('ZEPA', 'Zona de Especial Protección para las Aves: espacio protegido por la UE por su importancia para las aves.', 'conservación', NULL, 'NaturDex (divulgacion)'),
  ('LIC', 'Lugar de Importancia Comunitaria (LIC) y Zona Especial de Conservación (ZEC): espacios de la Red Natura 2000 protegidos por la UE.', 'conservación', '["ZEC"]', 'NaturDex (divulgacion)'),
  ('Red Natura 2000', 'Red europea de espacios naturales protegidos para conservar los hábitats y especies más valiosos del continente.', 'conservación', '["Natura 2000"]', 'NaturDex (divulgacion)'),
  ('albardinal', 'Formación vegetal dominada por el albardín, una hierba robusta propia de estepas y saladares del sureste español.', 'botánica', '["albardín"]', 'NaturDex (divulgacion)'),
  ('azufaifar', 'Matorral dominado por el azufaifo (arto), arbusto espinoso típico de zonas áridas del litoral mediterráneo.', 'botánica', '["azufaifo","arto"]', 'NaturDex (divulgacion)'),
  ('espartal', 'Pradera de esparto, hierba de hojas duras que forma extensas manchas en el sureste árido; se usó para cordelería.', 'botánica', '["esparto","atochar"]', 'NaturDex (divulgacion)'),
  ('psamófilo', 'Adaptado a vivir sobre la arena móvil de las dunas.', 'ecología', '["psamófila","psamófilos","psamófilas","dunar"]', 'NaturDex (divulgacion)'),
  ('sabinar', 'Bosque o matorral dominado por sabinas y enebros (género Juniperus), muy resistentes a la sequía.', 'botánica', '["sabina","enebro"]', 'NaturDex (divulgacion)'),
  ('semiárido', 'Clima con lluvias muy escasas e irregulares, en el límite de lo árido; característico del sureste peninsular.', 'clima', '["semiárida"]', 'NaturDex (divulgacion)'),
  ('garriga', 'Matorral mediterráneo bajo y denso sobre suelos calizos, con plantas aromáticas y espinosas.', 'botánica', '["garrigas"]', 'NaturDex (divulgacion)'),
  ('biogeografía', 'Estudio de cómo se distribuyen los seres vivos por el planeta y de las causas de esa distribución.', 'ciencia', '["biogeográfico","biogeográfica"]', 'NaturDex (divulgacion)'),
  ('Extinto (EX)', 'Categoría de la Lista Roja de la UICN. No queda ningún individuo vivo de la especie: se ha extinguido por completo.', 'conservación (UICN)', '["EX","Extinto","Extinta"]', 'NaturDex (divulgacion)'),
  ('Extinto en estado silvestre (EW)', 'Categoría UICN. Solo sobrevive en cultivo, cautividad o en poblaciones fuera de su área natural; ya no vive libre en la naturaleza.', 'conservación (UICN)', '["EW"]', 'NaturDex (divulgacion)'),
  ('En Peligro Crítico (CR)', 'Categoría UICN. Riesgo extremadamente alto de extinción en estado silvestre: la categoría de amenaza más grave antes de la extinción.', 'conservación (UICN)', '["CR"]', 'NaturDex (divulgacion)'),
  ('En Peligro (EN)', 'Categoría UICN. Riesgo muy alto de extinción en estado silvestre; la especie está claramente amenazada.', 'conservación (UICN)', '["EN","En Peligro"]', 'NaturDex (divulgacion)'),
  ('Vulnerable (VU)', 'Categoría UICN. Riesgo alto de extinción en estado silvestre: amenazada, aunque menos que En Peligro.', 'conservación (UICN)', '["VU","Vulnerable"]', 'NaturDex (divulgacion)'),
  ('Casi Amenazado (NT)', 'Categoría UICN. No está amenazada ahora mismo, pero está cerca de estarlo y podría pasar pronto a una categoría de amenaza.', 'conservación (UICN)', '["NT","Casi amenazado","Casi amenazada"]', 'NaturDex (divulgacion)'),
  ('Preocupación Menor (LC)', 'Categoría UICN. Especie abundante y extendida, con bajo riesgo de extinción; es la categoría más favorable.', 'conservación (UICN)', '["LC","Preocupación menor"]', 'NaturDex (divulgacion)'),
  ('Datos Insuficientes (DD)', 'Categoría UICN. No hay información suficiente para evaluar su riesgo de extinción; no significa que esté a salvo.', 'conservación (UICN)', '["DD","Datos insuficientes"]', 'NaturDex (divulgacion)'),
  ('No Evaluada (NE)', 'Categoría UICN. Todavía no se ha analizado con los criterios de la Lista Roja.', 'conservación (UICN)', '["NE","No evaluada"]', 'NaturDex (divulgacion)'),
  ('Extinto a nivel regional (RE)', 'Categoría UICN de ámbito regional. La especie ha desaparecido de una región concreta, aunque sobreviva en otras zonas.', 'conservación (UICN)', '["RE"]', 'NaturDex (divulgacion)'),
  ('CEEA', 'Catálogo Español de Especies Amenazadas: lista legal de las especies protegidas en España por estar en peligro, con dos categorías: En peligro de extinción y Vulnerable.', 'conservación', '["Catálogo Español de Especies Amenazadas"]', 'NaturDex (divulgacion)'),
  ('Libro Rojo', 'Obra que evalúa y publica el grado de amenaza de las especies de un territorio, siguiendo los criterios de la UICN.', 'conservación', NULL, 'NaturDex (divulgacion)'),
  ('ruderal', 'Propia de terrenos alterados por el ser humano: bordes de caminos, escombreras o cultivos abandonados.', 'ecología', '["ruderales"]', 'NaturDex (divulgacion)'),
  ('antrópico', 'Causado o influido por la actividad humana.', 'ecología', '["antrópica","antrópicos","antrópicas"]', 'NaturDex (divulgacion)'),
  ('alóctono', 'Traído de otra región por el ser humano; no es natural del lugar donde ahora aparece.', 'biogeografía', '["alóctona","alóctonos","alóctonas"]', 'NaturDex (divulgacion)'),
  ('xerófilo', 'Adaptado a vivir con muy poca agua, propio de ambientes secos.', 'ecología', '["xerófila","xerófilos","xerófilas","xerófito","xerófita"]', 'NaturDex (divulgacion)'),
  ('freatófito', 'Planta con raíces largas capaces de alcanzar el agua subterránea del subsuelo.', 'botánica', '["freatófita","freatófitos"]', 'NaturDex (divulgacion)'),
  ('perenne', 'Planta que vive varios años, en lugar de morir tras florecer una sola temporada.', 'botánica', '["perennes","vivaz","vivaces"]', 'NaturDex (divulgacion)'),
  ('anual', 'Planta que completa su ciclo de vida en un año y pasa la estación desfavorable en forma de semilla.', 'botánica', '["anuales","terófito","terófitos"]', 'NaturDex (divulgacion)'),
  ('perennifolio', 'Que mantiene las hojas verdes durante todo el año.', 'botánica', '["perennifolia","perennifolios"]', 'NaturDex (divulgacion)'),
  ('caducifolio', 'Que pierde las hojas en la estación desfavorable (otoño-invierno).', 'botánica', '["caducifolia","caducifolios"]', 'NaturDex (divulgacion)'),
  ('relicto', 'Superviviente de una flora o fauna antigua, hoy reducida a pequeñas zonas aisladas.', 'biogeografía', '["relíctico","relíctica","relictos"]', 'NaturDex (divulgacion)'),
  ('saladar', 'Terreno llano y encharcadizo con suelo muy salino, típico de marismas y depresiones litorales.', 'ecología', '["saladares"]', 'NaturDex (divulgacion)'),
  ('tomillar', 'Matorral bajo dominado por tomillos y otras plantas leñosas aromáticas.', 'botánica', '["tomillares"]', 'NaturDex (divulgacion)'),
