  ('esclerófilo', 'De hojas duras, gruesas y perennes, adaptadas a resistir la sequía; muy típico de la vegetación mediterránea.', 'botánica', '["esclerófila","esclerófilos","esclerófilas"]', 'NaturDex (divulgacion)'),
  ('coriáceo', 'De consistencia dura y resistente, parecida al cuero.', 'botánica', '["coriácea","coriáceos","coriáceas"]', 'NaturDex (divulgacion)'),
  ('umbela', 'Inflorescencia en la que los rabillos de las flores salen todos de un mismo punto y quedan a la misma altura, como las varillas de un paraguas.', 'botánica', '["umbelas"]', 'NaturDex (divulgacion)'),
  ('inflorescencia', 'Conjunto de flores agrupadas en una misma estructura (espiga, umbela, racimo...).', 'botánica', '["inflorescencias"]', 'NaturDex (divulgacion)'),
  ('capítulo', 'Inflorescencia con muchas flores pequeñas apretadas en una cabezuela, como en la margarita o el cardo.', 'botánica', '["capítulos"]', 'NaturDex (divulgacion)'),
  ('espiga', 'Inflorescencia alargada con flores pegadas, sin rabillo, a lo largo de un eje.', 'botánica', '["espigas"]', 'NaturDex (divulgacion)'),
  ('racimo', 'Inflorescencia alargada con flores unidas al eje por un rabillo, como en la uva.', 'botánica', '["racimos"]', 'NaturDex (divulgacion)'),
  ('cáliz', 'Envoltura externa de la flor, formada por los sépalos (normalmente verdes).', 'botánica', '["cálices"]', 'NaturDex (divulgacion)'),
  ('corola', 'Conjunto de los pétalos de la flor, a menudo la parte más vistosa y coloreada.', 'botánica', '["corolas"]', 'NaturDex (divulgacion)'),
  ('sépalo', 'Cada una de las piezas, normalmente verdes, que protegen la flor cuando está cerrada.', 'botánica', '["sépalos"]', 'NaturDex (divulgacion)'),
  ('pétalo', 'Cada una de las piezas, a menudo coloreadas, que forman la corola de la flor.', 'botánica', '["pétalos"]', 'NaturDex (divulgacion)'),
  ('bráctea', 'Hoja modificada, a veces coloreada, situada junto a las flores.', 'botánica', '["brácteas"]', 'NaturDex (divulgacion)'),
  ('peciolo', 'El rabillo que une la hoja al tallo.', 'botánica', '["peciolos","pecíolo","pecíolos"]', 'NaturDex (divulgacion)'),
  ('sésil', 'Que carece de rabillo y se une directamente al tallo (hoja o flor).', 'botánica', '["sésiles"]', 'NaturDex (divulgacion)'),
  ('foliolo', 'Cada una de las piezas en que se divide una hoja compuesta.', 'botánica', '["foliolos","folíolo","folíolos"]', 'NaturDex (divulgacion)'),
  ('pinnado', '(Hoja) dividida en foliolos dispuestos a ambos lados del nervio, como una pluma.', 'botánica', '["pinnada","pinnados","pinnadas"]', 'NaturDex (divulgacion)'),
  ('palmeado', '(Hoja) dividida en lóbulos que salen de un mismo punto, como los dedos de una mano.', 'botánica', '["palmeada","palmeados","palmeadas"]', 'NaturDex (divulgacion)'),
  ('lanceolado', '(Hoja) estrecha y puntiaguda, con forma de punta de lanza.', 'botánica', '["lanceolada","lanceolados","lanceoladas"]', 'NaturDex (divulgacion)'),
  ('lineal', '(Hoja) muy estrecha y alargada, de lados casi paralelos.', 'botánica', '["linear","lineales"]', 'NaturDex (divulgacion)'),
  ('tomentoso', 'Cubierto de pelillos cortos y densos, con aspecto afieltrado.', 'botánica', '["tomentosa","tomentosos","tomentosas"]', 'NaturDex (divulgacion)'),
  ('pubescente', 'Cubierto de pelillos finos y suaves.', 'botánica', '["pubescentes"]', 'NaturDex (divulgacion)'),
  ('glabro', 'Sin pelos, de superficie lisa.', 'botánica', '["glabra","glabros","glabras"]', 'NaturDex (divulgacion)'),
