  ('rizoma', 'Tallo subterráneo horizontal del que brotan raíces y nuevos tallos.', 'botánica', '["rizomas"]', 'NaturDex (divulgacion)'),
  ('bulbo', 'Tallo subterráneo engrosado que almacena reservas, como el de la cebolla.', 'botánica', '["bulbos"]', 'NaturDex (divulgacion)'),
  ('tubérculo', 'Engrosamiento subterráneo del tallo que almacena reservas, como la patata.', 'botánica', '["tubérculos"]', 'NaturDex (divulgacion)'),
  ('aquenio', 'Fruto seco que no se abre y contiene una sola semilla, como la ''pipa'' del girasol.', 'botánica', '["aquenios"]', 'NaturDex (divulgacion)'),
  ('legumbre', 'Fruto seco alargado que se abre por dos costuras, propio de las leguminosas.', 'botánica', '["legumbres"]', 'NaturDex (divulgacion)'),
  ('cápsula', 'Fruto seco que se abre al madurar para soltar las semillas.', 'botánica', '["cápsulas"]', 'NaturDex (divulgacion)'),
  ('drupa', 'Fruto carnoso con un hueso duro dentro, como la aceituna o la almendra.', 'botánica', '["drupas"]', 'NaturDex (divulgacion)'),
  ('baya', 'Fruto carnoso con varias semillas en su interior, como el tomate o la uva.', 'botánica', '["bayas"]', 'NaturDex (divulgacion)'),
