-- ================================================================================================
-- Aves de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope). Lista oficial: EEA/BISE Site_Species_List.
-- Taxonomia/estado desde EIDOS (IEPNB). Las aves NO se asignan a habitats (vuelan): se muestran en
-- un apartado propio de parque. Idempotente. zepa_site_code marca la pertenencia a la ZEPA.
-- ================================================================================================
-- 1) Marca las aves de la ZEPA que YA estaban en el catalogo.
UPDATE species sp JOIN parks p ON p.id = sp.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
  SET sp.zepa_site_code = 'ES0000261'
  WHERE sp.eidos_taxonid IN (16302, 10917, 11363, 11887, 10734, 10664, 11963, 11102, 12316, 11592, 80933, 80931);

-- 2) Alta de las aves oficiales de la ZEPA que faltaban (22), enriquecidas desde EIDOS.
