    conservation_status, description, identification_tips, seasonality, image_url, latitude, longitude,
    rarity_score, is_featured, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus,
    iucn_global, spain_status, murcia_status, eidos_taxonid, zepa_site_code)
