-- ================================================================================================
-- Enlaces especie-habitat CARACTERISTICOS respaldados por el Atlas y Manual de los Habitats de Espana
-- (MITECO). Backbone determinista: por cada HIC, las especies caracteristicas del Atlas que ADEMAS
-- estan presentes en el catalogo del parque (Atlas nacional interseccion flora del parque). 26 enlaces.
-- El Atlas confirma Teucrium freynii -> roquedos 8210 (no 5330/6220) y descarta los FP del heuristico.
-- Idempotente. evidence='caracteristica'.
-- ================================================================================================
INSERT INTO species_habitats (species_id, habitat_id, evidence)
SELECT sp.id, h.id, 'caracteristica'
FROM (
    SELECT 'Cakile maritima' scientific_name, 'veg-anual-desechos-marinos' habitat_slug
    UNION ALL
    SELECT 'Sarcocornia fruticosa' scientific_name, 'matorral-halofilo' habitat_slug
    UNION ALL
    SELECT 'Arthrocnemum macrostachyum' scientific_name, 'matorral-halofilo' habitat_slug
    UNION ALL
    SELECT 'Frankenia corymbosa' scientific_name, 'matorral-halofilo' habitat_slug
    UNION ALL
    SELECT 'Suaeda vera' scientific_name, 'matorral-halofilo' habitat_slug
    UNION ALL
    SELECT 'Withania frutescens' scientific_name, 'matorral-halonitrofilo' habitat_slug
    UNION ALL
    SELECT 'Limonium delicatulum' scientific_name, 'estepas-salinas-albardinal' habitat_slug
    UNION ALL
    SELECT 'Limonium insigne' scientific_name, 'estepas-salinas-albardinal' habitat_slug
    UNION ALL
    SELECT 'Maresia nana' scientific_name, 'dunas-malcomietalia' habitat_slug
    UNION ALL
    SELECT 'Maytenus senegalensis subsp. europaea' scientific_name, 'azufaifar' habitat_slug
    UNION ALL
    SELECT 'Periploca angustifolia' scientific_name, 'azufaifar' habitat_slug
    UNION ALL
    SELECT 'Salsola papillosa' scientific_name, 'matorral-semiarido' habitat_slug
    UNION ALL
    SELECT 'Teucrium lanigerum' scientific_name, 'matorral-semiarido' habitat_slug
    UNION ALL
    SELECT 'Sedum album' scientific_name, 'prados-alysso-sedion' habitat_slug
    UNION ALL
    SELECT 'Sedum sediforme' scientific_name, 'prados-alysso-sedion' habitat_slug
    UNION ALL
    SELECT 'Notoceras bicorne' scientific_name, 'subestepa-thero-brachypodietea' habitat_slug
    UNION ALL
    SELECT 'Plantago albicans' scientific_name, 'subestepa-thero-brachypodietea' habitat_slug
    UNION ALL
    SELECT 'Lygeum spartum' scientific_name, 'subestepa-thero-brachypodietea' habitat_slug
    UNION ALL
    SELECT 'Allium melananthum' scientific_name, 'subestepa-thero-brachypodietea' habitat_slug
    UNION ALL
    SELECT 'Lavandula multifida' scientific_name, 'subestepa-thero-brachypodietea' habitat_slug
    UNION ALL
    SELECT 'Hyparrhenia hirta' scientific_name, 'subestepa-thero-brachypodietea' habitat_slug
    UNION ALL
    SELECT 'Centaurea saxicola' scientific_name, 'roquedos-casmofiticos' habitat_slug
    UNION ALL
    SELECT 'Lafuentea rotundifolia' scientific_name, 'roquedos-casmofiticos' habitat_slug
    UNION ALL
    SELECT 'Teucrium freynii' scientific_name, 'roquedos-casmofiticos' habitat_slug
    UNION ALL
    SELECT 'Tamarix africana' scientific_name, 'galeria-ribera' habitat_slug
    UNION ALL
    SELECT 'Saccharum ravennae' scientific_name, 'galeria-ribera' habitat_slug
) rel
JOIN species sp ON sp.scientific_name = rel.scientific_name
JOIN habitats h ON h.slug = rel.habitat_slug
JOIN parks p ON p.id = sp.park_id AND p.id = h.park_id AND p.slug = 'cabo-cope-puntas-calnegre'
ON DUPLICATE KEY UPDATE evidence = 'caracteristica';

-- ================================================================================================
-- Especies exóticas INVASORAS de la Región de Murcia. Catálogo oficial: Catálogo Español de EEI
-- (RD 630/2013) vía EIDOS (IEPNB). Presencia y frecuencia ("más comunes"): GBIF (gadm ESP.14_1).
-- Las 25 más comunes por nº de ocurrencias. Idempotente. Apartado propio (no es flora del parque).
-- ================================================================================================
-- Especies exóticas INVASORAS de la Región de Murcia. Catálogo oficial: RD 630/2013 (EEI) vía EIDOS.
-- Presencia/frecuencia: GBIF (gadm ESP.14_1). Descripción, origen y hábitat: EIDOS (v_atributos_
-- pliniancore). Foto para reconocerla: GBIF media (iNaturalist, licencia CC). Idempotente.
-- ================================================================================================
INSERT INTO especies_invasoras (scientific_name, common_name, taxon_group, kingdom, ccaa, description, origin, habitat, catalogo, eidos_taxonid, gbif_species_key, gbif_occurrences, image_url, image_attribution, source) VALUES
  ('Psittacula krameri', 'Cotorra de Kramer', 'Aves', 'fauna', 'Región de Murcia', 'Cotorra de color verde pálido, con la cara y alas de un verde más intenso, la barbilla negra y la nuca un poco azulada. La cola, muy larga y afilada, es de un tono verde más oscuro, con las plumas centrales azuladas y la punta verde amarillento. El pico es corto y ganchudo, con la mandíbula superior de color rojo intenso y la inferior negra.', 'Originaria de África subsahariana e India.', 'Hábitat en su área de distribución natural En su área de distribución original, la especie ocupa todo tipo de zonas abiertas con árboles, sabanas arbustivas, bosques secundarios poco densos, etc.', 'Catálogo Español de EEI (RD 630/2013)', 10588, 2479226, 6470, 'https://inaturalist-open-data.s3.amazonaws.com/photos/605601324/original.jpg', 'Pedro (CC0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Myiopsitta monachus', 'Cotorra argentina', 'Aves', 'fauna', 'Región de Murcia', 'Longitud: 28-31 cm. De porte algo menor y más estilizado que una paloma. Adulto: Coloración general verde brillante. Frente, mejillas, garganta y pecho de color gris. Las plumas del pecho son de un gris más oscuro y presentan un márgen pálido, dando al pecho una apariencia escamosa. Vientre de color verde oliva. Rémiges y cobertoras primarias del ala, así como rectrices de la cola, de un verde azulado oscuro.', 'Sudamérica.', 'Hábitat en su área de distribución natural - La especie ocupa bosques de sabana semiárida, matorral de vegetación xerófita, arbolado de ribera, áreas abiertas con árboles dispersos, etc.', 'Catálogo Español de EEI (RD 630/2013)', 10468, 2479407, 3871, 'https://inaturalist-open-data.s3.amazonaws.com/photos/605083510/original.jpg', 'Zoltán Stekkelpak (CC0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Estrilda astrild', 'Pico de coral', 'Aves', 'fauna', 'Región de Murcia', 'Se caracteriza por su diminuto tamaño y su peculiar morfología, con cabeza pequeña, alas redondeadas muy cortas y cola en cuña. El plumaje del macho adulto en todas las épocas presenta color pardo mate en las zonas superiores y ocre en las inferiores, aunque ambas partes están finamente franjeadas en pardo oscuro. Tiene la garganta lisa, la parte inferior de la cola negra y la zona central del vientre roja.', 'Mundial. En el Paleártico occidental la población reproductora se distribuye mayoritariamente por la cuenca del Mediterráneo, principalmente en la península Ibérica, Italia, Grecia, norte de África, región de los…', NULL, 'Catálogo Español de EEI (RD 630/2013)', 10775, 2493660, 3128, 'https://inaturalist-open-data.s3.amazonaws.com/photos/608619233/original.jpg', 'S. Menéndez (CC BY 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Atlantoxerus getulus', 'Ardilla moruna', 'Mamíferos', 'fauna', 'Región de Murcia', 'Se trata de una ardilla terrestre cuyo aspecto es muy semejante al de la mayoría de las ardillas de suelo. Su cuerpo y cola están recorridos longitudinalmente por cuatro bandas negras y dos blancas. El pelo es corto, salvo la cola que es muy poblada, de pelo largo y denso, y con bandas longitudinales de colores pardo y oscuro.', 'Su rango nativo de distribución comprende el extremo noroeste de África: Marruecos, Gran y Medio Atlas, desde el sur de Agadir hasta el norte del Sahara y noroeste de Argelia.', 'En Fuerteventura ocupa todos los hábitats de la isla, estando presente desde altitudes a nivel del mar hasta las zonas más altas (en torno a 800 m) y siendo sólo significativamente menos abundante en las áreas ocupadas…', 'Catálogo Español de EEI (RD 630/2013)', 11356, 2437470, 2530, 'https://inaturalist-open-data.s3.amazonaws.com/photos/605045477/original.jpg', 'Pável Matos (CC BY-NC 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Nicotiana glauca', 'Tabaco moro', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Arbusto o pequeño árbol perennifolio generalmente de unos 3 m, aunque puede alcanzar hasta 7 m de altura. Es completamente glabro (no pubescente), con hojas gruesas de forma ovada a lanceolada de 5-25 cm de longitud, margen entero y color verde glauco, pecioladas y en disposición alterna. Las flores son amarillas y tubulares, de 3-4 cm de longitud, en panícula terminal.', 'Especie nativa del sur de Bolivia y noroeste de Argentina.', 'Hábitat en su área de distribución natural - Dentro de su rango nativo es una planta dispersa y raramente abundante de áreas secas y alteradas como canteras, orillas de ríos y bordes de carreteras.', 'Catálogo Español de EEI (RD 630/2013)', 6569, 2928783, 2524, 'https://inaturalist-open-data.s3.amazonaws.com/photos/605672681/original.jpg', 'Finlay F. K. Thorpe (CC BY-NC 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Streptopelia roseogrisea', 'Tórtola doméstica', 'Aves', 'fauna', 'Región de Murcia', 'Longitud: 29-30 cm. Envergadura: 45-50 cm. Muy difícil de diferenciar de la tórtola turca, es ligeramente más pequeña y de cola más corta que esta, y también más pálida, con vientre blanquecino, que contrasta con las plumas de vuelo y la cola oscuras. En vuelo aún resulta más evidente el contraste del cuerpo pálido con las alas oscuras.', 'Benin; Burkina Faso; Camerún; Chad; Djibouti; Egipto; Eritrea; Etiopia; Gambia; Kuwait; Mali; Mauritania; Níger; Nigeria; Arabia Saudí; Senegal; Somalia; Sudan; Western Sahara; Yemen.', 'Hábitat en su área de distribución natural - Bosques espinosos, riberas arenosas de ríos, zonas de cultivo, ciudades. Pueden realizar migraciones en la estación seca.', 'Catálogo Español de EEI (RD 630/2013)', 10601, 2495688, 2419, 'https://inaturalist-open-data.s3.amazonaws.com/photos/606140533/original.jpg', 'Cathal Moloney (CC BY-NC 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Ricinus communis', 'Ricino', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Planta herbácea alta de hasta 3-6 m., a veces algo arbustiva, de color verde claro a azulgrisáceo, en ocasiones rojiza. Hojas profundamente palmatilobada de 10-60 cm. de diámetro, divisiones de ovado-oblongas a lanceoladas, agudas o acuminadas, borde irregularmente dentado-glanduloso, pecíolos largos y rojizos, glándulas entre la lámina y el pecíolo.', 'África tropical.', 'Hábitat en su área de distribución natural - No se dispone de datos. Hábitat en su área de introducción - Terrenos de cultivos y zonas verdes de origen antrópico.', 'Catálogo Español de EEI (RD 630/2013)', 7788, 5380041, 2258, 'https://inaturalist-open-data.s3.amazonaws.com/photos/607160824/original.jpg', 'Marc Riera (CC BY 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Oxalis pes-caprae', 'Vinagrera', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Herbácea perenne, cespitosa, con un bulbo, en general menor de 2,5 cm, profundamente enterrado del que emerge un tallo subterráneo anual, ascendente, portador bulbillos y que acaba en una roseta de hojas situada al nivel del suelo. Pecíolos de hasta 20 cm. Limbos trifoliados, con folíolos de 8-20 x 12-30 mm, obcordiformes, profundamente emarginados, pruinosos por el envés.', 'Especie originaria de la región del Cabo, en Sudáfrica.', 'Hábitat en su área de distribución natural - No hay datos Hábitat en su área de introducción - Se desarrolla en aguas más o menos estancadas y de movimiento lento.', 'Catálogo Español de EEI (RD 630/2013)', 6897, 2891661, 2106, 'https://inaturalist-open-data.s3.amazonaws.com/photos/605332679/original.jpg', 'L Rose (CC BY 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Ageratina adenophora', 'Ageratina', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Se trata de un nanofanerófito perennifolio, aunque muchas veces se comporta como hemicriptófito al variar el grado de lignificación de los tallos, de hasta 1 m de altura, profusamente ramificado. Tallos, peciolos, ramas de la inflorescencia y pedicelos pelosos, con tricomas largos, simples y multicelulares y otros más o menos estipitados y glandulares.', 'Originaria de México y América Central', 'Hábitat en su área de distribución natural Se encuentra muy extendida, habitando en bosques de pinos o robles, y también en formaciones forestales tropicales, entre los 1.000 y 2.000 m de altitud Hábitat en su área de…', 'Catálogo Español de EEI (RD 630/2013)', 1075, 5400613, 1257, 'https://inaturalist-open-data.s3.amazonaws.com/photos/614233867/original.jpg', 'William Stephens (CC BY 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Agave americana', 'Pita', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Es una planta perenne, de porte robusto y rizomatosa. El tronco es casi inexistente o bien está ausente. Las hojas (que pueden medir hasta 2 metros de largo y 25 cm de ancho) crecen desde el suelo formando grandes rosetas, dispuestas hacia arriba y llegando a curvarse en el extremo hacia el suelo; son carnosas, robustas, en forma de lanza, y con espinas de casi 2 cm (muy agudas y finas, dando al margen un aspecto…', 'Se trata de una especie originaria del este de México.', 'Hábitat en su área de introducción Se trata de una planta termófila que en la región mediterránea habita en lugares pedregosos soleados, ramblas y arenales, por lo general cercanos al mar y más raramente en el interior.', 'Catálogo Español de EEI (RD 630/2013)', 1941, 2767031, 1175, 'https://inaturalist-open-data.s3.amazonaws.com/photos/610768542/original.jpg', 'Zoltán Stekkelpak (CC0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Cenchrus setaceus', 'Rabogato / plumero', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Hierba perenne de hasta 130 cm, formando densas macollas. Hojas con limbo enrollado, de hasta 30 cm x 3 mm, con una notoria costilla por el haz. Lígula reducida a una hilera de pelos. Inflorescencia en panícula cilíndrica de 6-30 cm, generalmente púrpura o rosada, con aspecto plumoso debido a la presencia de un involucro caedizo de finas cerdas, rodeando la base de cada grupo de espiguillas.', 'Especie originaria del nordeste de África, desde Túnez hasta Somalia.', 'Hábitat en su área de distribución natural Habita sobre suelos pedregosos y secos, así como en grietas de rocas. Hábitat en su área de introducción Pastizales y herbazales de ambientes alterados.', 'Catálogo Español de EEI (RD 630/2013)', 10093, 5828232, 1124, 'https://inaturalist-open-data.s3.amazonaws.com/photos/604647183/original.jpg', 'ohkaterina (CC BY-NC 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Pycnonotus cafer', 'Bulbul naranjero', 'Aves', 'fauna', 'Región de Murcia', 'Es un ave de tamaño mediano, de unos 20 cm de longitud y entre 26 y 45 gramos de peso. El macho y la hembra son similares, aunque el macho tiende a ser de mayor tamaño. La cabeza tiene una apariencia cuadrada debido a la corta cresta que luce. El pico y los ojos son negros. El cuerpo es de tonalidades oscuras (marrones, grisáceas o de color humo), la cabeza es casi negra y el abdomen blanco.', 'Pakistán, India, SRI Lanka e Indochina.', 'Hábitat en su área de distribución natural - Bosques y áreas agícolas Hábitat en su área de introducción - Vive en zonas de arbustos, en parques y jardines. También se encuentran en los bosques y áreas agrícolas.', 'Catálogo Español de EEI (RD 630/2013)', 10590, 2486131, 1113, 'https://inaturalist-open-data.s3.amazonaws.com/photos/607429906/original.jpg', 'Ricardo Rodero Henández (CC BY-NC 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Arundo donax', 'Caña común', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Planta herbácea, perenne, erecta, con raíces fuertes y carnosas. Tiene el tallo grueso y robusto, hueco; alcanza los 2-6 metros de altura y hasta 4 cm de diámetro. Es suave y glabro, brillante, simple o algo ramificado en los nudos; las cañas se dividen por tabiques en los nudos (como el bambú).', 'Este de Asia.', 'Hábitat en su área de distribución natural - Se desarrolla en lugares húmedos y encharcados, en acequias y cursos de agua.', 'Catálogo Español de EEI (RD 630/2013)', 9924, 2703041, 700, 'https://inaturalist-open-data.s3.amazonaws.com/photos/604777638/original.jpg', 'milandv (CC BY-NC 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Opuntia stricta', 'Chumbera', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Arbusto suculento de hasta 2 metros de alto, al principio erecto pero con tendencia a achaparrarse. Los tallos, transformados en cladodios (palas), son de color verde o verde azulado, aplanados, de 10-25 cm de largo y 7,5-15 cm de ancho, glabros, cubiertos de aréolas.', 'Sudeste de Estados Unidos (Florida, Luisiana, Alabama, Georgia, Carolina del Sur y Carolina del Norte), este de Méjico y Cuba.', 'Hábitat en su área de distribución natural No hay datos Hábitat en su área de introducción Roquedos silicios y terrazas de antiguos cultivos. 0-300 m.', 'Catálogo Español de EEI (RD 630/2013)', 6761, 5384075, 666, 'https://inaturalist-open-data.s3.amazonaws.com/photos/611235641/original.jpg', 'Michael Bakker Paiva (CC BY 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Opuntia dillenii', 'Chumbera de Dillen', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Arbusto de hasta 3 metros de alto (aunque no suele superar el metro), algo achaparrado, muy ramificado, con los tallos transformados en cladodios (palas), carnosos, suculentos, a menudo con los márgenes ondulados, de color verde-azulado, a veces gris verdoso. Miden de 7 a 40 cm de largo y de 6 a 9 de grosor.', 'Se trata de una especie ampliamente distribuida.', 'Hábitat en su área de introducción Eriales y matorrales desérticos. Zonas de matorral xerofítico del piso basal. Matorrales de ambientes costeros pero no excesivamente halófilos.', 'Catálogo Español de EEI (RD 630/2013)', 6757, 6378623, 489, 'https://inaturalist-open-data.s3.amazonaws.com/photos/633616473/original.jpg', 'woodpecker77 (CC BY-NC 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Calotropis procera', 'Manzana de Sodoma', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Según Scholz (2008) se trata de un pequeño árbol siempreverde con savia lechosa blanquecina. Presenta un tronco más o menos erecto, con corteza acorchada de color amarillo grisáceo. Sus hojas son grandes (hasta 20 x 15 cm), coriáceas y opuestas por pares. Las flores se presentan en inflorescencias axilares de un llamativo color violeta. Frutos en grandes folículos inflados de color verde.', 'Especie saharo-síndica (áreas desérticas desde el Sahara occidental y Marruecos hasta Pakistán, Afganistán y la India).', 'Hábitat en su área de distribución natural - Planicies desérticas arenosas o con suelos aluviales ricos en grava, preferentemente en cauces de barranco y cursos temporales de agua.', 'Catálogo Español de EEI (RD 630/2013)', 1523, 5414566, 440, 'https://inaturalist-open-data.s3.amazonaws.com/photos/614476749/original.jpg', 'Christian Berg (CC BY 4.0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Eschscholzia californica', 'Amapola de California', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Hierba de 20-60 cm de altura, con cierta pubescencia, erecta o decumbente, y que secreta un látex acuoso. Las hojas están largamente pecioladas, son de color verde azulado (glauco), con tres lóbulos finamente divididos y casi glabras.', 'Norteamérica (entre el río Columbia y la Baja Califórnia de norte a sur y desde el litoral del Océano Pacífico hasta el Gran Cañón).', 'Hábitat en su área de distribución natural - No se dispone de datos. Hábitat en su área de introducción - Pinares (pinares montanos secos sobre suelos desarrollados, pinares de cumbre), Pastizales y herbazales de…', 'Catálogo Español de EEI (RD 630/2013)', 4442, 2888380, 425, 'https://inaturalist-open-data.s3.amazonaws.com/photos/619024356/original.jpg', 'Jane Concannon (CC0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Ommatoiulus moreletii', 'Milpiés portugués', 'Invertebrados', 'fauna', 'Región de Murcia', 'Miriápodo robusto, de cuerpo cilíndrico y alargado, de color negro o gris negruzco, de 20-45 mm de largo, con el cuerpo compuesto de numerosos segmentos con dos pares de patas cada uno (unos 50 segmentos en estado maduro), aunque los primeros segmentos pueden portar sólo un par de patas. Huevos de color blanco amarillento.', 'Península ibérica.', 'Hábitat en su área de distribución natural - En su área de distribución natural vive normalmente al aire libre, en ambientes húmedos, donde se alimenta de hojarasca, madera en descomposición, hongos, raíces, musgos u…', 'Catálogo Español de EEI (RD 630/2013)', 10565, 4650395, 418, 'https://inaturalist-open-data.s3.amazonaws.com/photos/619608367/original.jpg', 'Mike Concannon (CC0) · GBIF', 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Ipomoea indica', 'Campanilla azul', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Planta perenne lianoide, con tallos volubles, cubiertos de pelos cuando son jóvenes; a veces segregar una savia lechosa al romperse. Las hojas son verdes o verde olivo en el haz, más claras en el envés, alternas, pecioladas, de hasta 20 cm, con 3 lóbulos patentes (los basales algo separados), en forma de corazón o de flecha, a veces con pequeños dientecillos en el margen.', 'Se trata de una especie de procedencia neotropical, aunque actualmente se encuentra extendida por casi todas las regiones tropicales y subtropicales del Planeta.', 'Hábitat en su área de distribución natural - No se dispone de datos. Hábitat en su área de introducción - Setos y herbazales ruderalizados cercanos a la costa. Terrenos de cultivos y zonas verdes de origen antrópico.', 'Catálogo Español de EEI (RD 630/2013)', 5375, 2928598, 415, NULL, NULL, 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Armadillidium vulgare', 'Cochinilla de la humedad', 'Invertebrados', 'fauna', 'Región de Murcia', 'Es un isópodo de buen tamaño, llegando a alcanzar los 18 mm de longitud. Como el resto de las “cochinillas”, es de forma ovalada, moderadamente aplanada por su parte dorsal, con el cuerpo aproximadamente el doble de largo que de ancho. La mayoría de los individuos presentan una coloración gris oscuro no brillante (gris pizarra), aunque a veces puede presentar pigmentaciones marrones o rojizas.', 'Se distribuye por toda Europa, especialmente en la región del Mediterráneo.', 'Hábitat en su área de distribución natural - Hábitat en las tierras húmedas de la región mediterránea. Hábitat en su área de introducción - Arenales costeros, terrenos de cultivos y zonas verdes de origen antrópico,…', 'Catálogo Español de EEI (RD 630/2013)', 10482, 2203611, 369, NULL, NULL, 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Centranthus ruber', 'Valeriana roja', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Hemicriptófito. Herbácea perenne de 30 a 80 cm. glabra. Tallos erectos simples o ramificados, lisos. Hojas ovales o elípticolanceolada de 8 a 12 cm. de largo y de 2 a 4 de ancho, enteras o un poco dentada, opuestas. Las inferiores pecioladas y las superiores sésiles. Flores muy numerosas, rojas o blancas con espolón, dispuestas en corimbos apretados que se alargan en panícula tricótoma. Fruto en aquenio glabro.', 'Cuenca mediterránea', 'Hábitat en su área de distribución natural - Crece predominantemente en suelos calcáreos en muros, acantilados, roquedos pedregales, desde el nivel del mar hasta 1300 m de altitud.', 'Catálogo Español de EEI (RD 630/2013)', 3374, 2888740, 312, NULL, NULL, 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Leucaena leucocephala', 'Leucaena', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Arbusto o pequeño árbol de 2 a 6 metros de altura, con el tronco leñoso de corteza gris-marrón con fisuras verticales superficiales de color óxido; las ramas jóvenes son pubescentes, y se vuelven glabras con la edad. Las estípulas son triangulares, diminutas y caducas.', 'Especie originaria de México y América Central.', 'Hábitat en su área de distribución natural - En zonas cálidas entre los 800 y 1700 m s.n.m., en clima tropical caluroso, con 5 meses de lluvia y con una pluviometría de 800 a 1200 mm anuales.', 'Catálogo Español de EEI (RD 630/2013)', 9616, 2970418, 312, NULL, NULL, 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Opuntia maxima', 'Chumbera', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Arbusto, a veces arborescente, que presenta un tronco bien desarrollado de hasta 35 cm de diámetro, de 1-4 m de altura, con los tallos transformados en cladodios (conocidos vulgarmente como palas) carnosos, suculentos, de estrechamente obovados a oblongos, aplanados, verdes, de 20-60 x 10-25 cm. Flores de color amarillo o rojizo, de 5-10 cm opuntia_maxima.doc Página 3 de 5 de diámetro.', 'América tropical, desde Méjico hasta Colombia.', 'Hábitat en su área de distribución natural Hábitats semiáridos. Hábitat en su área de introducción Resiste muy bien la sequía y los fuertes vientos marítimos.', 'Catálogo Español de EEI (RD 630/2013)', 6759, 5626003, 299, NULL, NULL, 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Threskiornis aethiopicus', 'Ibis sagrado', 'Aves', 'fauna', 'Región de Murcia', 'Ave de buen tamaño, con una longitud de 65 a 89 cm, una envergadura de 112-124 cm y un peso de aproximadamente 1,5 kg. Las hembras son algo más pequeñas que los machos. El plumaje del cuerpo es muy blanco, contrastando con la cabeza y cuello que son negros y sin plumas. El pico es largo, muy curvado hacia abajo, ancho en la base y de color negro. La punta de las plumas primarias y secundarias de las alas es negra.', 'Originaria de la región africana subsahariana, distribuyéndose por países africanos al sur del Sahara, Madagascar, sur de Irak e isla de Aldabra.', 'Hábitat en su área de distribución natural - Presente en zonas costeras, humedales de interior, en pastizales y praderas húmedas, en áreas de turberas, cultivos de regadío.', 'Catálogo Español de EEI (RD 630/2013)', 10510, 2480764, 232, NULL, NULL, 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)'),
  ('Carpobrotus edulis', 'Uña de gato', 'Plantas vasculares', 'flora', 'Región de Murcia', 'Es una planta reptante, con tallos largos muy ramificados, sub-cilíndricos, de hasta 3 metros y cortas ramas, dispuestos formando grandes esteras, a veces con raíces en los nudos. Las hojas son suculentas, sésiles, opuestas, de sección triangular, ligeramente adnatas en la base, cerosas, de color verde brillante o ligeramente glauco, a menudo teñidas de rojo a lo largo de los bordes.', 'Sudáfrica (El Cabo).', 'Hábitat en su área de distribución natural - Vive de manera natural entre el nivel del mar y los 1.000 m de altitud. Hábitat en su área de introducción - Zonas urbanizadas.', 'Catálogo Español de EEI (RD 630/2013)', 3174, 3084842, 227, NULL, NULL, 'Catálogo Español de EEI (RD 630/2013) vía EIDOS (IEPNB) para taxonomía, descripción, origen y hábitat; presencia y frecuencia: GBIF (Región de Murcia, gadm ESP.14_1)')
ON DUPLICATE KEY UPDATE common_name=VALUES(common_name), taxon_group=VALUES(taxon_group), kingdom=VALUES(kingdom), description=VALUES(description), origin=VALUES(origin), habitat=VALUES(habitat), catalogo=VALUES(catalogo), eidos_taxonid=VALUES(eidos_taxonid), gbif_species_key=VALUES(gbif_species_key), gbif_occurrences=VALUES(gbif_occurrences), image_url=VALUES(image_url), image_attribution=VALUES(image_attribution), source=VALUES(source);

